int intersections = 0;
for (int i = 0; i < numberOfChecks; ++i) {
    Vec3d direction = cg3::randomDirection();
    CGALPoint rayPoint(p.x(), p.y(), p.z());
    CGALPoint rayEnd(p.x() + direction.x(), p.y() + direction.y(), p.z() + direction.z());
    CGALRay ray(rayPoint, rayEnd);
    intersections += tree.number_of_intersected_primitives(ray);
}
return (intersections % 2) == 1;

